        super().__init__(parent)
        self.s = map_settings
        self._workshop = parent   # MapWorkshop instance - gives access to _WIDGET_REGISTRY
        self.setWindowTitle(App_name + " - Settings")
        self.setMinimumWidth(380)
        self.setModal(True)

