        tabs = QTabWidget()

        # - Canvas tab
        canvas_tab = QWidget()
        cl = QFormLayout(canvas_tab)
        cl.setSpacing(8)

        self._w_spin = QSpinBox(); self._w_spin.setRange(8, 4096)
        self._w_spin.setValue(self.s.get('default_width'))
