        pw = getattr(self, 'preview_widget', None)
        prev_row = QHBoxLayout(); prev_row.setSpacing(3)
        _prev_icons = {'solid':'solid_icon','textured':'texture_icon',
                        'semi':'semi_icon','wire':'wireframe_icon'}
