    def _set_select_mode(self, mode: str): #vers 3
        """Set viewport selection mode: vertex / edge / face / poly / object.
        Applied to every visible viewport (single or all 4 quad panes).
        Switching modes clears the other modes' selection sets, so there is
        no stale hidden selection left over when the user switches back."""
        for vp in self._live_viewports():
            vp._select_mode = mode
            if mode != 'vertex':
                vp._selected_verts.clear()
            if mode != 'edge':
                vp._selected_edges.clear()
            if mode not in ('face', 'poly'):
                vp._selected_faces.clear()
            vp.update()
        self._set_status(f"Select mode: {mode}")
        mw = self.main_window
        if mw and hasattr(mw, 'log_message'):
            mw.log_message(f"Model Workshop: select mode → {mode}")

    def _update_select_mode_availability(self): #vers 2
        """Enable vertex/edge/face/poly select buttons only when there is
        an actual model (DFF geometry or COL surfaces) to select from.
        Called after load, after creating a primitive from scratch, and
        whenever the active model is cleared."""
        has_dff = bool(getattr(self, '_current_dff_model', None) and
                       getattr(self._current_dff_model, 'geometries', None))
        has_col = bool(getattr(self, 'current_col_file', None) and
                       getattr(self.current_col_file, 'models', None))
        has_model = has_dff or has_col
        for attr in ('_sel_vert_btn', '_sel_edge_btn',
                     '_sel_face_btn', '_sel_poly_btn'):
            b = getattr(self, attr, None)
            if b:
                b.setEnabled(has_model)
        if not has_model:
            for vp in self._live_viewports():
                vp._select_mode = 'object'
                vp._selected_verts.clear()
                vp._selected_edges.clear()
                vp._selected_faces.clear()
                vp.update()
            grp = getattr(self, '_select_mode_group', None)
            if grp:
                grp.setExclusive(False)
                for attr in ('_sel_vert_btn', '_sel_edge_btn',
                             '_sel_face_btn', '_sel_poly_btn'):
                    b = getattr(self, attr, None)
                    if b: b.setChecked(False)
                grp.setExclusive(True)

    def _toggle_backface_cull(self): #vers 1
        """Toggle backface culling — when ON only the front face is visible/selectable."""
        vp = getattr(self, 'preview_widget', None)
        if not vp:
            return
        current = getattr(vp, '_backface', False)
        vp.set_backface(not current)
        state = "off (front+back)" if current else "on (front only)"
        self._set_status(f"Backface cull: {state}")

    def _toggle_front_only_paint(self): #vers 1
        """Toggle front-face-only paint — prevents painting geometry behind the current view."""
        vp = getattr(self, 'preview_widget', None)
        if not vp:
            return
        current = getattr(vp, '_front_only_paint', False)
        vp._front_only_paint = not current
        btn = getattr(self, '_front_paint_btn', None)
        if btn:
            btn.setChecked(not current)
        self._set_status(
            f"Front-only paint: {'ON — only visible faces painted' if not current else 'OFF'}")

    # - Primitive creation

    def _create_primitive_dialog(self): #vers 1
        """Show dialog to create a primitive shape (box or sphere) as a new DFF geometry."""
        from PyQt6.QtWidgets import (QDialog, QVBoxLayout, QHBoxLayout,
            QFormLayout, QLabel, QComboBox, QSpinBox, QDoubleSpinBox,
            QDialogButtonBox, QGroupBox)
        from PyQt6.QtCore import Qt as _Qt

        dlg = QDialog(self)
        dlg.setWindowTitle("Create Primitive")
        dlg.setMinimumWidth(300)
        lay = QVBoxLayout(dlg)
        form = QFormLayout()

        type_combo = QComboBox()
        type_combo.addItems(["Box", "Sphere", "Cylinder", "Plane"])
        form.addRow("Shape:", type_combo)

        # Dimensions
        dim_grp = QGroupBox("Dimensions")
        dim_lay = QFormLayout(dim_grp)
        sx = QDoubleSpinBox(); sx.setRange(0.01, 1000); sx.setValue(1.0); sx.setSingleStep(0.5)
        sy = QDoubleSpinBox(); sy.setRange(0.01, 1000); sy.setValue(1.0); sy.setSingleStep(0.5)
        sz = QDoubleSpinBox(); sz.setRange(0.01, 1000); sz.setValue(1.0); sz.setSingleStep(0.5)
        dim_lay.addRow("Width (X):",  sx)
        dim_lay.addRow("Height (Y):", sy)
        dim_lay.addRow("Depth (Z):",  sz)
        lay.addLayout(form)
        lay.addWidget(dim_grp)

        # Subdivisions
        sub_grp = QGroupBox("Subdivisions")
        sub_lay = QFormLayout(sub_grp)
        seg_x = QSpinBox(); seg_x.setRange(1, 64); seg_x.setValue(1)
        seg_y = QSpinBox(); seg_y.setRange(1, 64); seg_y.setValue(1)
        seg_z = QSpinBox(); seg_z.setRange(1, 64); seg_z.setValue(1)
        sub_lay.addRow("Segments X:", seg_x)
        sub_lay.addRow("Segments Y:", seg_y)
        sub_lay.addRow("Segments Z:", seg_z)
        lay.addWidget(sub_grp)

        # Hide irrelevant fields for sphere
        def _on_type_changed(t):  #vers 1
            is_box = t in ("Box", "Plane")
            seg_z.setEnabled(is_box)
            sz.setEnabled(t != "Plane")
        type_combo.currentTextChanged.connect(_on_type_changed)

        btns = QDialogButtonBox(
            QDialogButtonBox.StandardButton.Ok |
            QDialogButtonBox.StandardButton.Cancel)
        btns.accepted.connect(dlg.accept)
        btns.rejected.connect(dlg.reject)
        lay.addWidget(btns)

        if dlg.exec() != QDialog.DialogCode.Accepted:
            return

        shape  = type_combo.currentText()
        w, h, d = sx.value(), sy.value(), sz.value()
        nx, ny, nz = seg_x.value(), seg_y.value(), seg_z.value()

        try:
            verts, tris = self._build_primitive(shape, w, h, d, nx, ny, nz)
            self._add_geometry_to_dff(verts, tris, name=f"{shape.lower()}_01")
            self._set_status(
                f"Created {shape}: {w:.2f}×{h:.2f}×{d:.2f}  "
                f"segs {nx}×{ny}×{nz}  "
                f"({len(verts)} verts, {len(tris)} tris)")
        except Exception as e:
            from PyQt6.QtWidgets import QMessageBox
            QMessageBox.warning(self, "Primitive Error", str(e))

    def _extrude_dialog(self): #vers 1
        """Prompt for extrude distance and apply to the current face/poly
        selection in the viewport. Positive = outward, negative = inward
        (push-in, e.g. a recessed door/window/vent)."""
        from PyQt6.QtWidgets import QInputDialog, QMessageBox

        vp = getattr(self, 'preview_widget', None)
        if vp is None:
            return

        mode = getattr(vp, '_select_mode', 'face')
        if mode not in ('face', 'poly'):
            QMessageBox.information(self, "Extrude",
                "Switch to Face or Polygon select mode and select one or "
                "more faces first.")
            return

        if not getattr(vp, '_selected_faces', None):
            QMessageBox.information(self, "Extrude",
                "Select one or more faces first, then Extrude.")
            return

        distance, ok = QInputDialog.getDouble(
            self, "Extrude", "Distance (negative = push in):",
            0.5, -1000.0, 1000.0, 3)
        if not ok or distance == 0.0:
            return

        try:
            success = vp._extrude_selected_faces(distance)
            if success:
                self._set_status(f"Extruded {len(vp._selected_faces)} face(s) by {distance:.3f}")
            else:
                QMessageBox.warning(self, "Extrude",
                    "Nothing to extrude — load a DFF and select faces first.")
        except Exception as e:
            QMessageBox.warning(self, "Extrude Error", str(e))

    def _build_primitive(self, shape: str,
                          w: float, h: float, d: float,
                          nx: int, ny: int, nz: int):  #vers 1
        """Build vertex + triangle lists for a primitive.
        Returns (verts: list[(x,y,z)], tris: list[(i,j,k)])."""
        verts, tris = [], []

        if shape == "Box":
            # Generate a subdivided box
            # Each face: (nx×ny), (nx×nz), (ny×nz) quads → 2 tris each
            def _face_quad(p0, pu, pv, su, sv):  #vers 1
                """Add a subdivided quad face."""
                base = len(verts)
                for iv in range(sv + 1):
                    for iu in range(su + 1):
                        x = p0[0] + pu[0]*iu/su + pv[0]*iv/sv
                        y = p0[1] + pu[1]*iu/su + pv[1]*iv/sv
                        z = p0[2] + pu[2]*iu/su + pv[2]*iv/sv
                        verts.append((x, y, z))
                for iv in range(sv):
                    for iu in range(su):
                        i0 = base + iv*(su+1) + iu
                        i1 = i0 + 1
                        i2 = i0 + (su+1)
                        i3 = i2 + 1
                        tris.append((i0, i1, i2))
                        tris.append((i1, i3, i2))

            hw, hh, hd = w/2, h/2, d/2
            # +Y top
            _face_quad((-hw, hh, -hd), (w,0,0), (0,0,d), nx, nz)
            # -Y bottom
            _face_quad((-hw,-hh,  hd), (w,0,0), (0,0,-d), nx, nz)
            # +Z front
            _face_quad((-hw,-hh,  hd), (w,0,0), (0,h,0), nx, ny)
            # -Z back
            _face_quad((-hw,-hh, -hd), (w,0,0), (0,h,0), nx, ny)
            # -X left
            _face_quad((-hw,-hh, -hd), (0,0,d), (0,h,0), nz, ny)
            # +X right
            _face_quad(( hw,-hh,  hd), (0,0,-d), (0,h,0), nz, ny)

        elif shape == "Sphere":
            import math
            rings  = max(ny, 2)
            slices = max(nx * 2, 4)
            # Poles
            verts.append((0,  h/2, 0))  # top
            verts.append((0, -h/2, 0))  # bottom
            top_idx, bot_idx = 0, 1
            # Ring vertices
            for ri in range(1, rings):
                phi = math.pi * ri / rings
                y   = (h/2) * math.cos(phi)
                r   = (w/2) * math.sin(phi)
                for si in range(slices):
                    theta = 2 * math.pi * si / slices
                    verts.append((r * math.cos(theta), y, r * math.sin(theta)))
            ring_base = 2
            def _ri(ring, seg): return ring_base + ring * slices + (seg % slices)  #vers 1
            # Cap triangles
            for si in range(slices):
                tris.append((top_idx, _ri(0, si+1), _ri(0, si)))
                tris.append((bot_idx, _ri(rings-2, si), _ri(rings-2, si+1)))
            # Body quads
            for ri in range(rings - 2):
                for si in range(slices):
                    tris.append((_ri(ri,si), _ri(ri,si+1), _ri(ri+1,si)))
                    tris.append((_ri(ri,si+1), _ri(ri+1,si+1), _ri(ri+1,si)))

        elif shape == "Plane":
            hw, hd = w/2, d/2
            for iz in range(nz + 1):
                for ix in range(nx + 1):
                    verts.append((-hw + w*ix/nx, 0, -hd + d*iz/nz))
            for iz in range(nz):
                for ix in range(nx):
                    i0 = iz*(nx+1) + ix
                    i1 = i0 + 1
                    i2 = i0 + (nx+1)
                    i3 = i2 + 1
                    tris.append((i0, i1, i2))
                    tris.append((i1, i3, i2))

        elif shape == "Cylinder":
            import math
            slices = max(nx * 4, 8)
            hw, hh = w/2, h/2
            # Top + bottom centre
            verts.append((0,  hh, 0)); top_c = 0
            verts.append((0, -hh, 0)); bot_c = 1
            # Top ring
            top_base = len(verts)
            for si in range(slices):
                theta = 2*math.pi*si/slices
                verts.append((hw*math.cos(theta), hh, hw*math.sin(theta)))
            # Bottom ring
            bot_base = len(verts)
            for si in range(slices):
                theta = 2*math.pi*si/slices
                verts.append((hw*math.cos(theta), -hh, hw*math.sin(theta)))
            # Body quads + caps
            for si in range(slices):
                nsi = (si+1) % slices
                t0, t1 = top_base+si, top_base+nsi
                b0, b1 = bot_base+si, bot_base+nsi
                tris.append((t0, t1, b0))
                tris.append((t1, b1, b0))
                tris.append((top_c, t1, t0))
                tris.append((bot_c, b0, b1))

        return verts, tris

    def _add_geometry_to_dff(self, verts: list, tris: list,
                              name: str = "primitive"): #vers 2
        """Add a new geometry to the current DFF model from raw verts+tris.
        If no DFF model is loaded yet, creates a new blank one first so
        primitives can be built completely from scratch.
        Builds a real Geometry/Triangle/Vector3 (not a duck-typed stand-in)
        so the result is identical to a loaded DFF and saves correctly."""
        import math
        from apps.components.Model_Editor.depends.dff_classes import (
            DFFModel, Geometry, Triangle, Vector3, TexCoord, Frame, Atomic,
            BoundingSphere)

        model = getattr(self, '_current_dff_model', None)
        if model is None:
            # Nothing loaded — create a brand new empty model with one
            # root frame so the primitive has somewhere to attach.
            model = DFFModel()
            model.frames.append(Frame(name="root", parent_index=-1))
            self._current_dff_model = model
            self._current_dff_path = None
            self.current_col_file = None
            if hasattr(self, 'format_combo'):
                self.format_combo.setVisible(False)

        geom = Geometry()
        geom.vertices = [Vector3(x, y, z) for (x, y, z) in verts]
        geom.triangles = [Triangle(v1=i0, v2=i1, v3=i2, material_id=0)
                           for (i0, i1, i2) in tris]
        geom.uv_layers = [[TexCoord(0.0, 0.0) for _ in verts]]

        # Per-vertex normals: accumulate face normals, then normalise
        vert_normals = [[0.0, 0.0, 0.0] for _ in verts]
        for i0, i1, i2 in tris:
            v0, v1, v2 = verts[i0], verts[i1], verts[i2]
            ax, ay, az = v1[0]-v0[0], v1[1]-v0[1], v1[2]-v0[2]
            bx, by, bz = v2[0]-v0[0], v2[1]-v0[1], v2[2]-v0[2]
            nx = ay*bz - az*by
            ny = az*bx - ax*bz
            nz = ax*by - ay*bx
            ln = math.sqrt(nx*nx + ny*ny + nz*nz) or 1.0
            nx, ny, nz = nx/ln, ny/ln, nz/ln
            for idx in (i0, i1, i2):
                vert_normals[idx][0] += nx
                vert_normals[idx][1] += ny
                vert_normals[idx][2] += nz
        normals = []
        for nx, ny, nz in vert_normals:
            ln = math.sqrt(nx*nx + ny*ny + nz*nz) or 1.0
            normals.append(Vector3(nx/ln, ny/ln, nz/ln))
        geom.normals = normals

        # Bounding sphere — centre + radius enclosing all verts
        if verts:
            cx = sum(v[0] for v in verts) / len(verts)
            cy = sum(v[1] for v in verts) / len(verts)
            cz = sum(v[2] for v in verts) / len(verts)
            radius = max(math.sqrt((v[0]-cx)**2 + (v[1]-cy)**2 + (v[2]-cz)**2)
                         for v in verts)
            geom.bounding_sphere = BoundingSphere(center=Vector3(cx, cy, cz),
                                                   radius=radius)

        geom_index = len(model.geometries)
        model.geometries.append(geom)

        # New geometry needs a frame + atomic to attach to so the frame
        # hierarchy / Model Viewer can see it; attach to the root frame.
        model.atomics.append(Atomic(frame_index=0, geometry_index=geom_index))

        # Refresh viewport / mesh list
        self._display_dff_model(model)
        self._update_select_mode_availability()
        mw = self.main_window
        if mw and hasattr(mw, 'log_message'):
            mw.log_message(
                f"Primitive '{name}': {len(verts)} verts, {len(tris)} tris added to DFF")


    def _create_left_panel(self): #vers 7
        """Create left panel - COL file list (only in IMG Factory mode)"""
        # In standalone mode, don't create this panel
        if self.standalone_mode:
            self.col_list_widget = None  # Explicitly set to None
            return None

        if not self.main_window:
            # Standalone mode - return None to hide this panel
            return None

        # Only create panel in IMG Factory mode
        panel = QFrame()
        panel.setFrameStyle(QFrame.Shape.StyledPanel)
        panel.setMinimumWidth(200)
        panel.setMaximumWidth(300)

        layout = QVBoxLayout(panel)
        layout.setContentsMargins(5, 5, 5, 5)

        # Header row with search button
        hdr_row = QHBoxLayout()
        self._left_panel_header = QLabel("No files loaded")
        self._left_panel_header.setFont(self.panel_font)
        hdr_row.addWidget(self._left_panel_header)
        hdr_row.addStretch()

        self._model_search_btn = QPushButton()
        self._model_search_btn.setFixedSize(24, 24)
        self._model_search_btn.setToolTip("Search model files")
        try:
            from apps.methods.imgfactory_svg_icons import SVGIconFactory as _SVG
            self._model_search_btn.setIcon(_SVG.search_icon(16))
            self._model_search_btn.setIconSize(QSize(16, 16))
        except Exception:
            self._model_search_btn.setText("?")
        self._model_search_btn.clicked.connect(self._show_model_search)
        hdr_row.addWidget(self._model_search_btn)
        layout.addLayout(hdr_row)

        # Search box (hidden by default)
        self._model_search_box = QLineEdit()
        self._model_search_box.setPlaceholderText("Search model files...")
        self._model_search_box.setVisible(False)
        self._model_search_box.textChanged.connect(self._filter_model_list)
        layout.addWidget(self._model_search_box)

        self.col_list_widget = QListWidget()
        self.col_list_widget.setAlternatingRowColors(True)
        self.col_list_widget.itemClicked.connect(self._on_col_selected)
        layout.addWidget(self.col_list_widget)
        return panel


    def _create_models_table_panel(self): #vers 2
        """Create the Models table panel - mini toolbar + view toggle +
        model table only. Frame Hierarchy and Textures are now separate
        top-level dock widgets (see _create_frame_hierarchy_panel,
        _create_texture_panel), not stacked into this same panel -
        every section can be independently dragged/floated/docked now,
        same as Files already could."""
        panel = QFrame()
        panel.setFrameStyle(QFrame.Shape.StyledPanel)
        panel.setMinimumWidth(250)

        layout = QVBoxLayout(panel)
        layout.setContentsMargins(5, 5, 5, 5)
        layout.setSpacing(4)
        self._middle_panel_layout = layout

        # - Mini toolbar row: Open / Save / Import / Export / Undo / 3D View
        # (docked mode only) + the view-toggle button (always visible).
        # Previously the toggle had its own dedicated row above this one,
        # wasting a full row of height on just one small button - merged
        # into a single row instead.
        icon_color = self._get_icon_color()
        self._middle_btn_row = QFrame()
        btn_layout = QHBoxLayout(self._middle_btn_row)
        btn_layout.setContentsMargins(0, 0, 0, 0)
        btn_layout.setSpacing(3)

        # Collapse/expand toggle - hides the action icons below to reclaim
        # space, independent of the icon-only/icon+text compacting.
        self._mid_btn_row_collapsed = False
        self.mid_btn_collapse_btn = QPushButton("−")
        self.mid_btn_collapse_btn.setFixedSize(18, 28)
        self.mid_btn_collapse_btn.setToolTip("Collapse/expand this toolbar")
        self.mid_btn_collapse_btn.clicked.connect(self._toggle_mid_btn_row_collapsed)
        btn_layout.addWidget(self.mid_btn_collapse_btn)

        def _icon_btn(icon, tooltip, slot, enabled=True):  #vers 2
            b = QPushButton()
            b.setIcon(icon)
            b.setIconSize(QSize(20, 20))
            b.setFixedHeight(28)
            b.setMinimumWidth(28)
            b.setToolTip(tooltip)
            b.clicked.connect(slot)
            b.setEnabled(enabled)
            return b

        # Load (DFF + TXD + COL multi-select)
        self.open_col_btn = _icon_btn(
            self.icon_factory.open_icon(color=icon_color),
            "Load — DFF model, TXD textures, COL collision (multi-select)",
            self._open_dff_standalone)
        btn_layout.addWidget(self.open_col_btn)

        # Save
        self.save_col_btn = _icon_btn(
            self.icon_factory.save_icon(color=icon_color),
            "Save current file",
            self._save_file)
        btn_layout.addWidget(self.save_col_btn)

        # Import (other formats)
        self.import_btn = _icon_btn(
            self.icon_factory.import_icon(color=icon_color)
                if hasattr(self.icon_factory, 'import_icon')
                else self.icon_factory.open_icon(color=icon_color),
            "Import — MDL, OBJ, FBX and other formats",
            self._import_model)
        btn_layout.addWidget(self.import_btn)

        # Export (multiple formats — geometry + COL)
        self.export_col_btn = _icon_btn(
            self.icon_factory.multi_export_icon(color=icon_color),
            "Export — OBJ, COL, 3DS, FBX and other formats",
            self._export_model_menu)
        btn_layout.addWidget(self.export_col_btn)

        # Undo
        self.undo_col_btn = _icon_btn(
            self.icon_factory.undo_icon(color=icon_color),
            "Undo last change",
            self._undo_last_action)
        btn_layout.addWidget(self.undo_col_btn)

        # 3D View
        self._mini_3d_btn = _icon_btn(
            self.icon_factory.viewport_icon(color=icon_color),
            "Open GL Model Viewer",
            self._open_gl_viewer)
        btn_layout.addWidget(self._mini_3d_btn)

        btn_layout.addStretch()

        # View-toggle button - always visible regardless of dock state,
        # unlike the action icons above it.
        self._col_view_mode = 'detail'   # start in compact thumbnail view
        self.col_view_toggle_btn = QPushButton("[=]")
        self.col_view_toggle_btn.setFont(self.button_font)
        self.col_view_toggle_btn.setFixedWidth(32)
        self.col_view_toggle_btn.setFixedHeight(22)
        self.col_view_toggle_btn.setToolTip(
            "Toggle view: compact list ↔ full details table")
        self.col_view_toggle_btn.clicked.connect(self._toggle_col_view)
        btn_layout.addWidget(self.col_view_toggle_btn)

        layout.addWidget(self._middle_btn_row)
        self._middle_btn_row.setVisible(True)   # row itself always shown -
        # the toggle button lives here now, only the action icons below
        # are conditionally hidden when not docked.
        self._sync_middle_btn_row_visibility()
        # Register for adaptive compact display
        self._mid_compact_btns = [
            (getattr(self, 'open_col_btn',  None), "Open"),
            (getattr(self, 'save_col_btn',  None), "Save"),
            (getattr(self, 'import_btn',    None), "Import"),
            (getattr(self, 'export_col_btn',None), "Export"),
            (getattr(self, 'undo_col_btn',  None), "Undo"),
        ]

        # Hook the row's own resize event directly - self.resizeEvent()
        # only fires when the whole ModelWorkshop widget's outer bounding
        # box changes, but dragging the Models/viewport dock divider only
        # changes this row's own width (the outer tab doesn't resize at
        # all), so relying solely on self.resizeEvent() left the compact
        # check stuck at whatever it computed on first layout - possibly
        # wrong, and never re-evaluated afterwards.
        from PyQt6.QtWidgets import QFrame as _QFrameForResize
        _orig_mid_resize = self._middle_btn_row.resizeEvent
        def _mid_btn_row_resize(event, _orig=_orig_mid_resize):  #vers 1
            _orig(event)
            try:
                from apps.methods.imgfactory_ui_settings import apply_compact_buttons
                apply_compact_buttons(self._mid_compact_btns,
                                      self._middle_btn_row.width(),
                                      compact_threshold=320)
            except Exception:
                pass
        self._middle_btn_row.resizeEvent = _mid_btn_row_resize

        # - Model table (detail view)
        self.collision_list = QTableWidget()

        class _GuiLayout:
            def __init__(self, table):  #vers 1
                self.table = table
        self.gui_layout = _GuiLayout(self.collision_list)

        self.collision_list.setColumnCount(8)
        self.collision_list.setHorizontalHeaderLabels([
            "Name", "Format", "RW Version", "Size",
            "Verts", "Tris", "Materials", "UV Layers"])
        self.collision_list.setSelectionBehavior(
            QAbstractItemView.SelectionBehavior.SelectRows)
        self.collision_list.setSelectionMode(
            QAbstractItemView.SelectionMode.ExtendedSelection)
        self.collision_list.setAlternatingRowColors(True)
        self.collision_list.itemSelectionChanged.connect(self._on_collision_selected)
        self.collision_list.horizontalHeader().setStretchLastSection(True)
        self.collision_list.setContextMenuPolicy(
            Qt.ContextMenuPolicy.CustomContextMenu)
        self.collision_list.customContextMenuRequested.connect(
            self._show_collision_context_menu)
        self.collision_list.setVisible(False)  # hidden at startup — compact view is default
        layout.addWidget(self.collision_list)

        # - Compact list (thumbnail + name/version/counts, single row)
        self.mod_compact_list = QTableWidget()
        self.mod_compact_list.setColumnCount(2)
        self.mod_compact_list.setHorizontalHeaderLabels(["Preview", "Details"])
        self.mod_compact_list.horizontalHeader().setStretchLastSection(True)
        self.mod_compact_list.setSelectionBehavior(
            QAbstractItemView.SelectionBehavior.SelectRows)
        self.mod_compact_list.setSelectionMode(
            QAbstractItemView.SelectionMode.ExtendedSelection)
        self.mod_compact_list.setAlternatingRowColors(True)
        self.mod_compact_list.setIconSize(QSize(64, 64))
        self.mod_compact_list.itemSelectionChanged.connect(
            self._on_compact_col_selected)
        self.mod_compact_list.setContextMenuPolicy(
            Qt.ContextMenuPolicy.CustomContextMenu)
        self.mod_compact_list.customContextMenuRequested.connect(
            self._show_collision_context_menu)
        self.mod_compact_list.setVisible(True)    # start in compact view
        self.mod_compact_list.setRowCount(0)      # populated on first file load
        self.mod_compact_list.setWordWrap(True)
        self.mod_compact_list.setItemDelegate(_ModelListDelegate(self.mod_compact_list))
        layout.addWidget(self.mod_compact_list)

        # Model Name / IDE-TXD ribbons - built here but docked into the
        # middle panel's own nested QMainWindow below, not added to this
        # layout directly. Split into two so they can be moved
        # independently of each other.
        self._info_ribbons = {
            'name': self._build_model_name_toolbar(),
            'ide':  self._build_model_ide_toolbar(icon_color),
        }
        self._info_ribbon_location = {'name': 'middle', 'ide': 'middle'}

        return self._wrap_middle_panel_with_own_dock_areas(panel)

    def _create_frame_hierarchy_panel(self): #vers 2
        """Create the Frame Hierarchy panel on its own - previously stacked
        inside the same panel as the model table/textures, now a separate
        top-level dock widget so it can be independently dragged/floated.
        No internal header row - the dock's own title bar already shows
        'Frame Hierarchy', and collapsing is now done by double-clicking
        that title bar (see _make_dock_collapsible) instead of a per-panel
        toggle button."""
        from PyQt6.QtWidgets import QTreeWidget
        self._frame_tree_panel = QFrame()
        self._frame_tree_panel.setFrameStyle(QFrame.Shape.StyledPanel)
        ft_lay = QVBoxLayout(self._frame_tree_panel)
        ft_lay.setContentsMargins(2, 2, 2, 2)
        ft_lay.setSpacing(2)

        self._frame_tree = QTreeWidget()
        self._frame_tree.setHeaderLabels(["Frame", "Parent", "Position"])
        self._frame_tree.setAlternatingRowColors(True)
        self._frame_tree.setFont(self.panel_font)
        self._frame_tree.itemClicked.connect(self._on_frame_tree_clicked)
        ft_lay.addWidget(self._frame_tree)

        return self._frame_tree_panel

    def _toggle_dock_floating(self, dock): #vers 1
        """Toggle a dock's floating state, explicitly positioning/sizing
        and raising the resulting floating window. Plain setFloating()
        alone can leave a dock with a custom title bar at an odd,
        overlapping, or effectively invisible position/size - looking
        like nothing happened to the target dock, while its neighbours
        still visibly resize to fill the space it vacated (which is
        what actually tipped this off - the dock genuinely was floating,
        just not anywhere the user could see it)."""
        was_floating = dock.isFloating()
        dock.setFloating(not was_floating)
        if not was_floating:
            # Just floated - make sure it's a reasonable size and visibly
            # placed near this workshop's own window, then bring it to front.
            if dock.width() < 200 or dock.height() < 150:
                dock.resize(320, 400)
            anchor = self.mapToGlobal(self.rect().center())
            dock.move(anchor.x() - dock.width() // 2,
                      anchor.y() - dock.height() // 2)
            dock.show()
            dock.raise_()
            dock.activateWindow()

    def _make_dock_collapsible(self, dock, title): #vers 4
        """Custom title bar for a QDockWidget: double-click anywhere on the
        title (label or empty bar area) to collapse the dock down to just
        this title bar, hiding its content; double-click again to restore.
        Keeps float/close buttons so nothing is lost versus Qt's native
        title bar - only mouseDoubleClickEvent is overridden, so single-
        click-and-drag (moving the dock) still works exactly as before,
        since that's handled by mousePressEvent/mouseMoveEvent, untouched
        here. Known rough edges tracked in TODO.md (missing splitter
        between some panels, right-click recovery menu, the disabled
        float/dock button below)."""

        from PyQt6.QtWidgets import QWidget as _QW, QToolButton as _QTB

        bar = _QW()
        lay = QHBoxLayout(bar)
        lay.setContentsMargins(6, 2, 2, 2)
        lay.setSpacing(2)

        lbl = QLabel(title)
        lbl.setFont(self.section_title_font)
        dock._title_label = lbl   # exposed so callers can update the visible
                                  # title dynamically later (Aug 1 2026)
                                  # IPL Inst File "turns into IDE
                                  # Objects" when the IDE tab is selected)
        lay.addWidget(lbl)
        lay.addStretch()

        #float_btn = _QTB()
        #float_btn.setText("⧉") #keep disabled for now.
        #float_btn.setToolTip("Float/dock")
        #float_btn.setFixedSize(20, 20)
        #float_btn.setAutoRaise(True)
        #float_btn.clicked.connect(lambda: self._toggle_dock_floating(dock))
        #lay.addWidget(float_btn)

        close_btn = _QTB()
        close_btn.setText("×")
        close_btn.setToolTip("Close (use the View menu or another dock's right-click menu to bring it back)")
        close_btn.setFixedSize(20, 20)
        close_btn.setAutoRaise(True)
        close_btn.clicked.connect(dock.close)
        lay.addWidget(close_btn)

        def _dbl_click(event, d=dock): #vers 1
            content = d.widget()
            if content:
                content.setVisible(not content.isVisible())
        bar.mouseDoubleClickEvent = _dbl_click
        lbl.mouseDoubleClickEvent = _dbl_click

        dock.setTitleBarWidget(bar)

    def _make_section_collapsible(self, label, content_widget): #vers 1
        """Double-click a section's bold title label to collapse/restore
        the content widget below it - same double-click-to-collapse
        interaction as dock title bars (_make_dock_collapsible), just
        applied to a sub-section within a panel instead of a whole
        dock. Used for the IMG/IDE/IPL/DAT tabs inside Object Browser."""
        def _dbl_click(event, w=content_widget): #vers 1
            w.setVisible(not w.isVisible())
        label.mouseDoubleClickEvent = _dbl_click
        existing_tip = label.toolTip()
        label.setToolTip((existing_tip + "\n" if existing_tip else "") +
                         "Double-click to collapse/expand")

    def _wrap_middle_panel_with_own_dock_areas(self, content_panel): #vers 4
        """Give the middle panel its own nested QMainWindow (same pattern
        the right panel already uses for the viewport), so the Name and
        IDE/TXD ribbons have real Left/Right toolbar dock areas specifically
        flanking the middle panel's own content - not just the option of
        living inside it as a plain widget, or all the way over on the
        far-right ribbon stack. Both default to the bottom (closest to
        their old combined position), but can be dragged to either side
        independently within this mini QMainWindow, or moved to the main
        right panel via the existing right-click action."""
        from PyQt6.QtWidgets import QMainWindow
        middle_mw = QMainWindow()
        middle_mw.setWindowFlags(Qt.WindowType.Widget)
        middle_mw.setDockOptions(
            QMainWindow.DockOption.AllowNestedDocks |
            QMainWindow.DockOption.AllowTabbedDocks)
        # Same explicit separator styling as outer_mw - prevents the
        # docked-mode theme-cascade issue that zeroed out separator
        # visibility from affecting this nested QMainWindow too.
        middle_mw.setStyleSheet(
            "QMainWindow::separator { "
            "background: palette(mid); width: 5px; height: 5px; } "
            "QMainWindow::separator:hover { background: palette(highlight); }")
        middle_mw.setCentralWidget(content_panel)
        middle_mw.addToolBar(Qt.ToolBarArea.BottomToolBarArea, self._info_ribbons['name'])
        # Explicit break so IDE always sits on its own row below Name,
        # instead of sharing one row whenever there's enough width.
        middle_mw.addToolBarBreak(Qt.ToolBarArea.BottomToolBarArea)
        middle_mw.addToolBar(Qt.ToolBarArea.BottomToolBarArea, self._info_ribbons['ide'])
        self._middle_mw = middle_mw
        return middle_mw

    def _build_model_name_toolbar(self): #vers 2
        """Build the 'Model Name: Click to edit...' ribbon on its own,
        split out from the combined Model Info ribbon so it can be
        independently docked/moved from the IDE/TXD one."""
        from PyQt6.QtWidgets import QToolBar
        tb = QToolBar("Model Name")
        tb.setObjectName("Model Name")
        tb.setIconSize(QSize(18, 18))
        tb.setMovable(True)
        tb.setFloatable(True)
        tb.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        tb.customContextMenuRequested.connect(
            lambda pos, t=tb, key='name': self._info_ribbon_menu(t, pos, key))

        name_label = QLabel("Model Name:")
        name_label.setFont(self.panel_font)
        tb.addWidget(name_label)

        self.info_name = QLineEdit()
        self.info_name.setText("Click to edit...")
        self.info_name.setFont(self.panel_font)
