    def _refresh_img_tab(self, loader): #vers 1
        """Rebuild the numbered IMG sub-tabs from the loaded world's
        actual IMG archives (loader.get_img_paths()) - one table per
        archive, listing every entry's real name/type/size read
        directly from the archive itself."""
        img_tabs = getattr(self, '_img_tab_tabs', None)
        if img_tabs is None:
            return
        img_tabs.clear()
        from apps.methods.img_core_classes import IMGFile
        for i, img_path in enumerate(loader.get_img_paths(), 1):
            table = QTableWidget(0, 4)
            table.setHorizontalHeaderLabels(["Ind.", "Filename", "Type", "Size"])
            table.setEditTriggers(QTableWidget.EditTrigger.NoEditTriggers)
            table.horizontalHeader().setSectionResizeMode(1, QHeaderView.ResizeMode.Stretch)
            self._apply_compact_table_style(table)
            try:
                img = IMGFile(img_path)
                if img.open():
                    table.setRowCount(len(img.entries))
                    for row, entry in enumerate(img.entries):
                        table.setItem(row, 0, QTableWidgetItem(str(row)))
                        table.setItem(row, 1, QTableWidgetItem(entry.name))
                        table.setItem(row, 2, QTableWidgetItem(entry.extension.upper() + " File"
                                                                if entry.extension else "File"))
                        size_kb = max(1, entry.size // 1024)
                        table.setItem(row, 3, QTableWidgetItem(f"{size_kb} kB"))
            except Exception:
                pass
            img_tabs.addTab(table, str(i))


    def _create_editing_panel_dock(self): #vers 1
        """New tabbed "Editing Panel" dock - IDE/IPL/DAT/IMG, matching
        MooMapper's own tabbed IMG Archive/Object Definition/Item
        Placement structure - replaces the previous standalone IPL
        Sections dock (its content now lives in the [IPL] tab, moved
        rather than duplicated). [IPL] is the only fully real,
        interactive tab so far; [IDE] and [DAT] show real data
        (IDE file list, raw .dat text) but can't edit/save yet;
        [IMG] shows real per-archive entry lists but can't
        Extract/Add/Del/Rename yet - none of this project has any
        write-back-to-disk infrastructure yet, for any file type."""
        icon_color = self._get_icon_color()
        tabs = QTabWidget()
        tabs.addTab(self._create_ide_tab(),
                   self._render_variant_icon('tab_ide', None, 24, icon_color, has_menu=False), "IDE")
        tabs.addTab(self._create_ipl_tab(),
                   self._render_variant_icon('tab_ipl', None, 24, icon_color, has_menu=False), "IPL")
        tabs.addTab(self._create_dat_tab(),
                   self._render_variant_icon('tab_dat', None, 24, icon_color, has_menu=False), "DAT")
        tabs.addTab(self._create_img_tab(),
                   self._render_variant_icon('tab_img', None, 24, icon_color, has_menu=False), "IMG")
        tabs.setCurrentIndex(1)   # [IPL] is the main working tab so far

        dock = QDockWidget("Editing Panel", self)
        dock.setObjectName("Editing Panel")
        dock.setWidget(tabs)
        dock.setFeatures(QDockWidget.DockWidgetFeature.DockWidgetMovable |
                        QDockWidget.DockWidgetFeature.DockWidgetFloatable |
                        QDockWidget.DockWidgetFeature.DockWidgetClosable)
        self._editing_panel_dock = dock
        self._editing_panel_tabs = tabs
        return dock

    def _on_ipl_section_cell_clicked(self, row, col): #vers 5
        """Clicking the eye-icon cell (col 0) toggles that IPL's
        visibility - plain item click rather than a button, so there's
        no button widget/chrome to size or pad. Clicking anywhere else
        on the row just selects it, which is enough to refresh the IPL
        Inst File panel below)"""
        if getattr(self, '_ipl_cell_click_in_progress', False):
            return
        self._ipl_cell_click_in_progress = True
        table = self._ipl_sections_table
        try:
            item = table.item(row, 0)
            if item is None:
                return
            display_name = item.data(Qt.ItemDataRole.UserRole)
            if col == 0:
                ipl_name = display_name
                hidden = ipl_name in getattr(self, '_hidden_ipls', set())
                new_hidden = not hidden
                if not new_hidden:
                    # Disable the whole table for the duration of the
                    # actual load (Aug 1 2026)
                    table.setEnabled(False)
                    try:
                        self._ensure_ipl_loaded(ipl_name)
                    finally:
                        table.setEnabled(True)
                    # Re-locate the row by name, not the original row
                    # index (Aug 1 2026, same crash)
                    item = None
                    for r in range(table.rowCount()):
                        candidate = table.item(r, 0)
                        if candidate is not None and candidate.data(Qt.ItemDataRole.UserRole) == ipl_name:
                            item = candidate
                            row = r
                            break
                    if item is None:
                        return   # row no longer exists post-rebuild - nothing left to update
                item.setIcon(self._eye_closed_icon if new_hidden else self._eye_open_icon)
                item.setToolTip(f"Show {ipl_name}" if new_hidden else f"Hide {ipl_name}")
                name_item = table.item(row, 1)
                if name_item is not None:
                    loader = getattr(self, '_world_loader', None)
                    if ipl_name in getattr(self, '_ipl_names_with_binary_stream', {}) or \
                            display_name in getattr(self, '_loaded_binary_ipls', set()):
                        row_is_loaded = display_name in getattr(self, '_loaded_binary_ipls', set())
                    else:
                        stem_for_load_check = getattr(self, '_ipl_display_to_stem', {}).get(ipl_name)
                        row_is_loaded = (loader is not None and stem_for_load_check is not None
                                         and stem_for_load_check in loader.loaded_ipls)
                    self._style_ipl_name_item(name_item, new_hidden, row_is_loaded)
                self._toggle_ipl_section(ipl_name, new_hidden)
            self._auto_switch_ipl_tab_if_empty(display_name)
            self._refresh_ipl_inst_file_panel()
        finally:
            self._ipl_cell_click_in_progress = False

    def _ipl_section_has_data(self, raw_text, section_name): #vers 1
        """True if `section_name` exists in raw_text AND has at least
        one real data line - not just the bare keyword/end pair (Aug
        15 2026)"""
        section_lines = self._extract_ipl_section_text(raw_text, section_name)
        if not section_lines:
            return False
        for line_no, raw_line in section_lines:
            line = raw_line.split("#")[0].strip()
            low = line.lower()
            if not line or low in (section_name, 'end'):
                continue
            return True
        return False

    def _auto_switch_ipl_tab_if_empty(self, display_name): #vers 1
        """If the currently active IPL Controls tab (INST/CULL/PATH/
        etc) has no real data in the just-selected file, switch to
        the first enabled tab that does (Aug 15 2026)"""
        bar = getattr(self, '_ipl_tab_bar', None)
        keys = getattr(self, '_ipl_tab_keys', None)
        loader = getattr(self, '_world_loader', None)
        if bar is None or keys is None or loader is None or not display_name:
            return
        stem = getattr(self, '_ipl_display_to_stem', {}).get(display_name)
        if stem is None or stem.startswith('img:'):
            return
        entry = loader.available_ipls.get(stem)
        if entry is None or not entry.exists:
            return
        try:
            with open(entry.abs_path, 'r', encoding='ascii', errors='ignore') as f:
                raw_text = f.read()
        except Exception:
            return

        current_type = getattr(self, '_ipl_data_type', 'inst')
        if self._ipl_section_has_data(raw_text, current_type):
            return
        for idx, key in enumerate(keys):
            if key == current_type or not bar.isTabEnabled(idx):
                continue
            if self._ipl_section_has_data(raw_text, key):
                bar.blockSignals(True)
                bar.setCurrentIndex(idx)
                bar.blockSignals(False)
                self._ipl_data_type = key
                return

    def _on_ipl_section_cell_double_clicked(self, row, col): #vers 1
        """Double-click any cell in an IPL Sections row to open/show
        that IPL (Aug 14 2026)"""
        if getattr(self, '_ipl_cell_click_in_progress', False):
            return
        table = self._ipl_sections_table
        item = table.item(row, 0)
        if item is None:
            return
        ipl_name = item.data(Qt.ItemDataRole.UserRole)
        if ipl_name in getattr(self, '_hidden_ipls', set()):
            self._on_ipl_section_cell_clicked(row, 0)

    def _ensure_ipl_loaded(self, display_name): #vers 3
        """Actually load one IPL's content on demand, the first time
        it's toggled visible - parses its instances (GTAWorldLoader.
        load_ipl_by_name), refreshes self._all_instances/Object Browser
        with the newly-added data, and pre-loads (with a progress
        dialog scoped to just this IPL's models, not the whole world)
        the geometry/textures those new instances reference. A no-op
        if this IPL was already loaded (or lazy loading isn't active
        at all, e.g. a non-Map-Workshop caller)."""

        loader = getattr(self, '_world_loader', None)
        if loader is None or not getattr(loader, 'lazy_ipl_loading', False):
            return
        stem = getattr(self, '_ipl_display_to_stem', {}).get(display_name)
        if stem is None:
            return

        if stem.startswith('img:'):
            if display_name in getattr(self, '_loaded_binary_ipls', set()):
                return   # already loaded via _load_binary_ipl_stream
            archive_path = getattr(self, '_standalone_binary_ipl_archives', {}).get(display_name)
            if archive_path is None:
                self._set_status(f"{display_name}: no known archive to load it from")
                return
            self._load_binary_ipl_stream(archive_path, display_name)
            return

        if stem in loader.loaded_ipls:
            return   # not a lazily-tracked IPL, or already loaded

        before_count = len(loader.instances)
        result = loader.load_ipl_by_name(stem)
        if not result.success:
            self._set_status(f"{display_name} failed to load"
                             + (f" - {result.errors[0]}" if result.errors else ""))
            return

        problem_count = result.error_count + result.warning_count
        if problem_count:
            log_path = self._write_ipl_error_log(result)
            self._set_status(
                f"{display_name} loaded - {problem_count} issue(s) found"
                + (f", check {os.path.basename(log_path)} added to the maps folder"
                   if log_path else ""))
        else:
            self._set_status(f"{display_name} loaded - no errors "
                             f"({result.instance_count} instances)")

        new_instances = loader.instances[before_count:]

        self._all_instances = list(loader.instances)
        self._populate_object_browser(loader)

        model_cache = getattr(self, '_model_cache', None)

        # Auto-load associated binary streams (Aug 1 2026)
        stream_entries = getattr(self, '_ipl_names_with_binary_stream', {}).get(display_name, [])
        verbose = self.map_settings.get('show_verbose_loading_dialog')
        bulk_loading = getattr(self, '_shared_load_progress', None) is not None
        dlg = None
        if verbose and not bulk_loading and (new_instances or stream_entries):
            # Suppressed during a bulk multi-IPL load (Aug 20 2026,
            # per Keith: "this opens multiple dialogues. It should be
            # one window") - _load_selected_ipl_sections' own real,
            # shared progress dialog already reports which IPL is
            # loading; a separate detailed log window per IPL on top
            # of that would still be exactly the "multiple dialogues"
            # gap this fix is for, just moved to a different dialog.
            dlg = _VerboseLoadingDialog(f"Loading {display_name}", self)
            dlg.show()
            n_streams = len(stream_entries) if self.map_settings.get('load_text_plus_binary_ipl_set') else 0
            dlg.add_header(f"Loading {display_name} and {n_streams} binary ipls.")
            for inst in new_instances:
                dlg.add_line(f"{inst.model_id}, {inst.model_name}")

        if model_cache is not None and new_instances:
            self._preload_world_assets(
                loader, model_cache, instances=new_instances,
                title=f"Loading {display_name}…")

        if self.map_settings.get('load_text_plus_binary_ipl_set'):
            for archive_path, stream_name in sorted(stream_entries, key=lambda t: t[1]):
                if stream_name in getattr(self, '_loaded_binary_ipls', set()):
                    continue
                if dlg is not None:
                    dlg.add_header(f"Loading linked ipl file {stream_name}")
                before_stream_count = len(getattr(self, '_all_instances', []))
                self._load_binary_ipl_stream(archive_path, stream_name)
                if dlg is not None:
                    new_stream_instances = self._all_instances[before_stream_count:]
                    for inst in new_stream_instances:
                        dlg.add_line(f"{inst.model_id}, {inst.model_name}")

    def _write_ipl_error_log(self, result): #vers 1
        """Write a plain-text log of one IPL's parse errors/warnings
        alongside the IPL file itself (same folder)"""
        if not result.abs_path:
            return None
        try:
            folder = os.path.dirname(result.abs_path)
            base = os.path.splitext(os.path.basename(result.abs_path))[0]
            log_path = os.path.join(folder, f"{base}_load_errors.log")
            with open(log_path, 'w', encoding='utf-8') as f:
                f.write(f"Load errors for {result.abs_path}\n")
                f.write(f"{result.error_count} error(s), {result.warning_count} warning(s)\n\n")
                if result.errors:
                    f.write("Errors:\n")
                    for e in result.errors:
                        f.write(f"  - {e}\n")
                if result.warnings:
                    f.write("\nWarnings:\n")
                    for w in result.warnings:
                        f.write(f"  - {w}\n")
            return log_path
        except Exception:
            return None

    def _style_ipl_name_item(self, name_item, hidden, loaded=False): #vers 4
        """Grey out a disabled/hidden IPL's name text. Real fix (Aug
        20 2026, per Keith: "once proloaded, mark them as loaded
        white in the obj browser ipl llst") - loaded entries now get
        a genuinely brighter/white text colour, not just the existing
        "(Loaded)" text suffix, so a loaded IPL is visually distinct
        from an unloaded one at a glance, not just readable on close
        inspection."""
        pal = self.palette()
        text_color = pal.color(pal.ColorGroup.Active, pal.ColorRole.Text)
        if hidden:
            bg_color = pal.color(pal.ColorGroup.Active, pal.ColorRole.Window)
            color = QColor(
                (text_color.red()   + bg_color.red())   // 2,
                (text_color.green() + bg_color.green()) // 2,
                (text_color.blue()  + bg_color.blue())  // 2)
        elif loaded:
            color = QColor(255, 255, 255)
        else:
            color = text_color
        name_item.setForeground(QBrush(color))

    def _toggle_ipl_section(self, ipl_name, hidden): #vers 2
        """Show/hide all instances from one IPL file - recomputes the
        visible instance subset from the full loaded set and re-feeds
        it to the world-view panes and Instance List, without needing
        to reload from disk.

        clear_display_lists=False (Aug 1 2026)"""
        if hidden:
            self._hidden_ipls.add(ipl_name)
        else:
            self._hidden_ipls.discard(ipl_name)
        self._apply_ipl_visibility_filter(clear_display_lists=False)

    # --- World viewport, LOD, ribbon/menu framework (ported from map_workshop_old_version.py) ---

    def _create_centre_panel(self): #vers 4
        """Map Workshop's own centre panel - status bar only. No DP5-style
        bitmap canvas here (removed Jul 31 2026)"""
        panel = QWidget()
        self._centre_panel = panel
        layout = QVBoxLayout(panel)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)

        # Status bar - built here but NOT added to this panel's own layout.
        # It becomes outer_mw's native status bar instead (see setup_ui) -
        # QMainWindow's built-in status bar always spans the full window
        # width, whereas embedding it in this panel meant it only got
        # whatever width was left after the right-side dock widgets took
        # their share, squeezing/covering its right-aligned permanent
        # widgets.
        self._status_bar = QStatusBar()
        self._status_bar.setSizeGripEnabled(False)
        self._status_bar.setFixedHeight(22)
        self._status_bar.setVisible(self.map_settings.get('show_statusbar'))

        return panel

    def _get_tool_menu_style(self) -> str: #vers 1
        """Read menu_style from map_settings."""
        return self.map_settings.get('menu_style', 'dropdown')

    def _apply_menu_bar_style(self): #vers 3
        """Apply font size, height and colours to the topbar menubar.
        Uses explicit colours so it stays readable regardless of app theme.
        """
        mb = getattr(self, '_menu_bar', None)
        if not mb:
            return
        bar_h  = self.map_settings.get('menu_bar_height', 22)
        bar_fs = self.map_settings.get('menu_bar_font_size', 9)
        dd_fs  = self.map_settings.get('menu_dropdown_font_size', 9)

        # Get theme colours if available, otherwise use sensible defaults
        bg   = '#2b2b2b'
        fg   = '#e0e0e0'
        sel  = '#1976d2'
        selfg = '#ffffff'
        border = '#555555'
        try:
            app_settings = getattr(self, 'app_settings', None)
            if not app_settings and self.main_window:
                app_settings = getattr(self.main_window, 'app_settings', None)
            if app_settings:
                tc = app_settings.get_theme_colors() or {}
                bg    = tc.get('bg_primary',   bg)
                fg    = tc.get('text_primary',  fg)
                sel   = tc.get('accent',        sel)
                border = tc.get('border',       border)
        except Exception:
            pass

        # Height controlled by container — NOT by stylesheet min/max-height
        # (stylesheet height properties override Qt layout and prevent the bar showing)
        mb.setStyleSheet(f"""
            QMenuBar {{
                background-color: {bg};
                color: {fg};
                border-bottom: 1px solid {border};
                font-size: {bar_fs}pt;
            }}
            QMenuBar::item {{
                background-color: transparent;
                padding: 2px 6px;
            }}
            QMenuBar::item:selected {{
                background-color: {sel};
                color: {selfg};
            }}
            QMenu {{
                background-color: {bg};
                color: {fg};
                border: 1px solid {border};
                font-size: {dd_fs}pt;
            }}
            QMenu::item:selected {{
                background-color: {sel};
                color: {selfg};
            }}
        """)

        # Size the container based on settings, not isVisible() 
        # (isVisible() is False during __init__ even if widget will be shown)
        c = getattr(self, '_menu_bar_container', None)
        if c:
            show = (self.map_settings.get('show_menubar', False) and
                    self.map_settings.get('menu_style', 'dropdown') == 'topbar')
            if show:
                c.setMinimumHeight(0)
                c.setMaximumHeight(bar_h)
            # Don't touch height here if hiding — setup_ui and set_menu_orientation handle that


    def set_menu_orientation(self, style: str): #vers 5
        """Switch DP5 menu between 'topbar' (internal) and 'dropdown' (host menubar).
        When docked the internal bar is always suppressed regardless of style —
        imgfactory's top bar owns the menus via ToolMenuMixin injection.
        """
        self.map_settings.set('menu_style', style)
        self.map_settings.set('show_menubar', style == 'topbar')

        container = getattr(self, '_menu_bar_container', None) or getattr(self, '_menu_bar', None)
        if container:
            if style == 'topbar' and self.standalone_mode:
                # Only show internal bar in standalone mode
                container.setMinimumHeight(0)
                container.setMaximumHeight(16777215)
                container.setVisible(True)
                container.updateGeometry()
                self._apply_menu_bar_style()
            else:
                # Docked always hides internal bar; dropdown mode always hides it too
                container.setVisible(False)
                container.setMinimumHeight(0)
                container.setMaximumHeight(0)
                container.setFixedHeight(0)

        # Notify imgfactory to inject/remove tool menu when docked
        if not self.standalone_mode:
            mw = getattr(self, 'main_window', None)
            if mw and hasattr(mw, 'menu_bar_system'):
                if style == 'dropdown':
                    mw.menu_bar_system._inject_tool_menu(self)
                else:
                    mw.menu_bar_system._remove_tool_menu()


    def _toggle_menubar(self, on: bool): #vers 3
        self.map_settings.set('show_menubar', on)
        self.map_settings.save()
        c = getattr(self, '_menu_bar_container', self._menu_bar if hasattr(self, '_menu_bar') else None)
        if c:
            c.setMinimumHeight(0)
            c.setMaximumHeight(16777215 if on else 0)
            c.setVisible(on)


    def _toggle_statusbar(self, on: bool): #vers 1
        self.map_settings.set('show_statusbar', on)
        self.map_settings.save()
        if hasattr(self, '_status_bar'):
            self._status_bar.setVisible(on)


    def _preload_img_archives_to_os_cache(self, img_paths): #vers 1
        """Sequentially read through every given IMG archive once,
        discarding the bytes - the only purpose is letting the OS
        cache the file in RAM ahead of time, so later per-model reads
        during actual IPL loading hit cache instead of disk (Aug 16
        2026)"""
        CHUNK = 8 * 1024 * 1024
        for img_path in img_paths:
            try:
                size = os.path.getsize(img_path)
            except OSError:
                continue
            if size <= 0:
                continue
            name = os.path.basename(img_path)
            size_mb = size / (1024 * 1024)
            try:
                with open(img_path, 'rb') as f:
                    read_so_far = 0
                    while True:
                        chunk = f.read(CHUNK)
                        if not chunk:
                            break
                        read_so_far += len(chunk)
                        pct = int(100 * read_so_far / size)
                        self._set_status(
                            f"Preloading {name} ({size_mb:.1f} MB)... {pct}%")
                        QApplication.processEvents()
            except OSError as e:
                self._set_status(f"Preloading {name} failed: {e}")
                QApplication.processEvents()
                continue
        self._set_status("Ready")

    def _preload_world_assets(self, loader, model_cache, instances=None, title=None): #vers 3
        """Eagerly load+parse (and cache) geometry and textures for
        every distinct model referenced by the given instances (or
        every loaded instance, if none given), with a progress dialog
        showing what's currently being processed.

        Real fix (Aug 20 2026, per Keith: "when selecting multiply
        ipls, all select, load all, this opens multiple dialogues. It
        should be one window with the title and process change") -
        this used to always create its own new QProgressDialog every
        call; _ensure_ipl_loaded calls this once per IPL, so loading
        several IPLs at once (via _load_selected_ipl_sections' own
        loop) meant a separate dialog popping open and closing for
        each one in turn. Now checks self._shared_load_progress first
        - when the caller has already set one up (see _load_selected_
        ipl_sections' own real usage), this reuses that same one
        window instead of creating a second, redundant one; a single-
        IPL caller (e.g. clicking one eye icon) leaves that attribute
        unset, so it still gets its own dialog exactly as before."""
        instances = instances if instances is not None else loader.instances
        # Deduplicate by model_name - many instances share one model,
        # no need to load it more than once.
        seen_models = {}
        for inst in instances:
            if inst.model_name not in seen_models:
                obj = loader.get_object(inst.model_id)
                txd_name = obj.txd_name if obj else ""
                seen_models[inst.model_name] = (txd_name, inst.source_ipl)
        if not seen_models:
            return

        items = list(seen_models.items())
        shared = getattr(self, '_shared_load_progress', None)
        if shared is not None:
            progress = shared
        else:
            progress = QProgressDialog(
                title or "Loading assets…", "Cancel", 0, len(items), self)
            progress.setWindowTitle("Loading Meshes and Textures")
            progress.setMinimumDuration(500)   # don't flash up for fast loads
            progress.setWindowModality(Qt.WindowModality.WindowModal)

        loaded_txds = set()
        for i, (model_name, (txd_name, source_ipl)) in enumerate(items):
            if progress.wasCanceled():
                self._set_status(
                    f"Asset loading cancelled after {i} of {len(items)} models "
                    f"- remaining models will still load on demand while browsing")
                break
            progress.setLabelText(
                f"{(title + chr(10)) if (shared is not None and title) else ''}"
                f"Model: {model_name}\nTexture: {txd_name or '(none)'}\nIPL: {source_ipl}")
            if shared is None:
                progress.setValue(i)
            model_cache.get_geometry(model_name)
            if txd_name and txd_name not in loaded_txds:
                model_cache.get_textures(txd_name)
                loaded_txds.add(txd_name)
        if shared is None:
            progress.setValue(len(items))

    def _toggle_cull_boxes(self, checked): #vers 1
        """Show/hide wireframe cull zone boxes across all World View
        panes - real, working feature using GTAWorldLoader.culls (see
        MapViewport._draw_cull_boxes for the honest caveat on the
        field-interpretation assumption)."""
        loader = getattr(self, '_world_loader', None)
        culls = loader.culls if loader is not None else []
        for pane in getattr(self, '_world_panes', []):
            pane.set_cull_boxes(culls, checked)

    def _apply_ipl_visibility_filter(self, auto_fit=True, clear_display_lists=True): #vers 6
        """Recompute which instances are currently visible: every
        loaded instance whose source_ipl isn't in self._hidden_ipls,
        then layer LOD show/hide on top (global toggle + any per-
        instance overrides) - push the final result to the world-view
        panes and Instance List.

        Reentrancy guard, corrected (Aug 16 2026)

        clear_display_lists=False (Aug 1 2026)"""
        if getattr(self, '_apply_ipl_visibility_filter_in_progress', False):
            self._apply_ipl_visibility_filter_pending = (auto_fit, clear_display_lists)
            return
        self._apply_ipl_visibility_filter_in_progress = True
        try:
            self._apply_ipl_visibility_filter_impl(auto_fit, clear_display_lists)
            while True:
                pending = getattr(self, '_apply_ipl_visibility_filter_pending', None)
                if pending is None:
                    break
                self._apply_ipl_visibility_filter_pending = None
                self._apply_ipl_visibility_filter_impl(*pending)
        finally:
            self._apply_ipl_visibility_filter_in_progress = False

    def _apply_ipl_visibility_filter_impl(self, auto_fit, clear_display_lists): #vers 1
        """The actual body of _apply_ipl_visibility_filter, split out
        only so the reentrancy guard above can wrap it in a try/
        finally without a second level of indentation - not meant to
        be called directly by anything else; call _apply_ipl_
        visibility_filter instead."""
        all_inst = getattr(self, '_all_instances', None)
        if all_inst is None:
            return
        hidden = getattr(self, '_hidden_ipls', set())
        visible = [i for i in all_inst if i.source_ipl not in hidden] if hidden else all_inst
        visible = self._apply_lod_filter(visible)
        visible = self._apply_tobj_time_filter(visible)
        for pane in getattr(self, '_world_panes', []):
            pane.set_instances(visible)
        loader_stub = _FilteredLoaderStub(visible, getattr(self, '_world_loader', None))
        self._populate_instance_list(loader_stub)
        self._refresh_world_view(visible, auto_fit=auto_fit, clear_display_lists=clear_display_lists)
        self._refresh_2dfx_lights(visible)
        self._refresh_path_visualization()
        self._refresh_cull_box_visualization()
        self._refresh_zone_box_visualization()
        self._refresh_occl_box_visualization()
        self._refresh_auzo_visualization()
        self._refresh_water_visualization()

    def _refresh_2dfx_lights(self, visible_instances): #vers 1
        """Collect 2DFX light-type (effect_type == 0) entries for the
        given visible instances, compute each one's world-space
        position, and push them to the viewport."

        "At night" (Aug 1 2026)"""
        vp = getattr(self, 'preview_widget', None)
        loader = getattr(self, '_world_loader', None)
        if vp is None or loader is None or not hasattr(vp, 'set_2dfx_lights'):
            return
        master_chk = getattr(self, '_2dfx_master_chk', None)
        if master_chk is not None and not master_chk.isChecked():
            vp.set_2dfx_lights([])
            return
        get_2dfx = getattr(loader, 'get_2dfx_for_model', None)
        if get_2dfx is None:
            vp.set_2dfx_lights([])
            return

        chk = getattr(self, '_tobj_time_chk', None)
        if chk is not None and chk.isChecked():
            hour = self._tobj_time_spin.time().hour()
            is_night = hour >= 20 or hour < 6
            if not is_night:
                vp.set_2dfx_lights([])
                return

        lights = []
        for inst in visible_instances:
            for fx in get_2dfx(inst.model_id):
                if fx.extra.get('effect_type') != 0:
                    continue
                ox = fx.extra.get('offset_x', 0.0)
                oy = fx.extra.get('offset_y', 0.0)
                oz = fx.extra.get('offset_z', 0.0)
                # Effective (conjugated) rotation, not the raw stored
                # quaternion (Aug 1 2026)
                erx, ery, erz, erw = self._effective_rotation(inst)
                wx, wy, wz = self._rotate_and_translate_offset(
                    ox, oy, oz, erx, ery, erz, erw,
                    inst.pos_x, inst.pos_y, inst.pos_z)
                r = fx.extra.get('color_r', 255)
                g = fx.extra.get('color_g', 255)
                b = fx.extra.get('color_b', 255)
                a = fx.extra.get('color_a', 255)
                size = fx.extra.get('corona_size', 1.0)
                lights.append((wx, wy, wz, r, g, b, a, size))
        vp.set_2dfx_lights(lights)

    def _refresh_path_visualization(self): #vers 2
        """Push the currently visible IPLs' path data to the
        viewport's line/node overlay (Aug 14 2026)

        Builds the REAL per-node link graph (Aug 16 2026)"""
        vp = getattr(self, 'preview_widget', None)
        if vp is None or not hasattr(vp, 'set_path_segments'):
            return
        show_paths_chk = getattr(self, '_show_paths_chk', None)
        if show_paths_chk is not None and not show_paths_chk.isChecked():
            if hasattr(vp, 'set_path_node_owners'):
                vp.set_path_node_owners({})
            vp.set_path_segments([])
            return
        # Apply the saved line colour/thickness and node colour/size
        # every refresh, not just when the Settings dialog is used to
        # change them (Aug 14/16 2026) - so a value picked in a
        # previous session is already in effect the first time paths
        # are shown this session, without needing a separate "apply
        # saved settings on startup" hook.
        if hasattr(vp, 'set_path_line_color'):
            saved_color = self.map_settings.get('path_line_color') or (255, 0, 0)
            cr, cg, cb = saved_color
            vp.set_path_line_color(cr / 255.0, cg / 255.0, cb / 255.0)
        if hasattr(vp, 'set_path_node_color'):
            saved_node_color = self.map_settings.get('path_node_color') or (255, 204, 0)
            ncr, ncg, ncb = saved_node_color
            vp.set_path_node_color(ncr / 255.0, ncg / 255.0, ncb / 255.0)
        if hasattr(vp, 'set_path_line_thickness'):
            vp.set_path_line_thickness(self.map_settings.get('path_line_thickness') or 1.2)
        if hasattr(vp, 'set_path_node_size'):
            vp.set_path_node_size(self.map_settings.get('path_node_size') or 3.5)
        if hasattr(vp, 'set_track_color'):
            tcr, tcg, tcb = self.map_settings.get('track_color') or (191, 191, 204)
            vp.set_track_color(tcr / 255.0, tcg / 255.0, tcb / 255.0)
        if hasattr(vp, 'set_track_line_thickness'):
            vp.set_track_line_thickness(self.map_settings.get('track_line_thickness') or 1.5)
        if hasattr(vp, 'set_airtrain_color'):
            acr, acg, acb = self.map_settings.get('airtrain_color') or (230, 153, 51)
            vp.set_airtrain_color(acr / 255.0, acg / 255.0, acb / 255.0)
        if hasattr(vp, 'set_airtrain_line_thickness'):
            vp.set_airtrain_line_thickness(self.map_settings.get('airtrain_line_thickness') or 1.2)
        loader = getattr(self, '_world_loader', None)
        if loader is None:
            if hasattr(vp, 'set_path_node_owners'):
                vp.set_path_node_owners({})
            vp.set_path_segments([])
            return
        hidden = getattr(self, '_hidden_ipls', set())
        visible_groups = [g for g in getattr(loader, 'paths', [])
                           if g.source_ipl not in hidden and g.nodes]

        segments = []
        # (position -> (group, node_index)) for interactive path node
        # dragging (Aug 17 2026)
        node_owners = {}
        for group in visible_groups:
            nodes = group.nodes
            n = len(nodes)
            for i, node in enumerate(nodes):
                if node.node_type == 0:
                    continue   # Null node - ignored, per the format doc
                node_owners[(node.x, node.y, node.z)] = (group, i)
                if 0 <= node.next_id < n:
                    other = nodes[node.next_id]
                    segments.append(((node.x, node.y, node.z), (other.x, other.y, other.z)))

        # GTA III IDE-embedded paths (Aug 16 2026)

        instances_by_model = {}
        for inst in getattr(loader, 'instances', []):
            if inst.source_ipl in hidden:
                continue
            instances_by_model.setdefault(inst.model_id, []).append(inst)

        # Scope each group's model_id lookup to every currently-
        # visible instance sharing that model_id, globally - no per-
        # area scoping (Aug 16 2026)
        for group in getattr(loader, 'ide_paths', []):
            matching_instances = instances_by_model.get(group.model_id)
            if not matching_instances:
                continue
            nodes = group.nodes
            n = len(nodes)
            for inst in matching_instances:
                ex, ey, ez, ew = self._effective_rotation(inst)
                world_pos = []
                for node in nodes:
                    # /16 scale on the relative offsets (Aug 16 2026)

                    wx, wy, wz = self._rotate_vector_by_quaternion(
                        node.x_rel / 16.0, node.y_rel / 16.0, node.z_rel / 16.0,
                        ex, ey, ez, ew)
                    world_pos.append((inst.pos_x + wx, inst.pos_y + wy, inst.pos_z + wz))
                for i, node in enumerate(nodes):
                    if node.node_type == 0:
                        continue
                    if 0 <= node.next_id < n:
                        segments.append((world_pos[i], world_pos[node.next_id]))

        if hasattr(vp, 'set_path_node_owners'):
            vp.set_path_node_owners(node_owners)
        vp.set_path_segments(segments)

    def _on_path_node_dragged(self, group, node_index, new_x, new_y, new_z): #vers 1
        """Commit a completed path node drag to the real, live
        PathNode data (Aug 17 2026)"""
        try:
            node = group.nodes[node_index]
        except (IndexError, AttributeError):
            return
        node.x, node.y, node.z = new_x, new_y, new_z
        self._refresh_path_visualization()
        self._set_status(f"Moved path node to ({new_x:.1f}, {new_y:.1f}, {new_z:.1f})")

